using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Restaurant.Application.Infrastructure;
using Restaurant.Domain.Events;

namespace Restaurant.Application.BackgroundServices;

/// <summary>
/// Background service that processes CompanyCustomerMealPlanAutoGeneratedEvent events from a channel
/// </summary>
public class MealPlanAutoGeneratedEventHandler : BackgroundService
{
    private readonly ChannelEventPublisher<CompanyCustomerMealPlanAutoGeneratedEvent> _eventPublisher;
    private readonly ILogger<MealPlanAutoGeneratedEventHandler> _logger;

    public MealPlanAutoGeneratedEventHandler(
        ChannelEventPublisher<CompanyCustomerMealPlanAutoGeneratedEvent> eventPublisher,
        ILogger<MealPlanAutoGeneratedEventHandler> logger)
    {
        _eventPublisher = eventPublisher;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("MealPlanAutoGeneratedEventHandler started");

        await foreach (var @event in _eventPublisher.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {
                await ProcessEventAsync(@event, stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Error processing CompanyCustomerMealPlanAutoGeneratedEvent for CompanyCustomerId: {CompanyCustomerId}, MealPlanId: {MealPlanId}",
                    @event.CompanyCustomerId, @event.CompanyCustomerMealPlanId);
            }
        }

        _logger.LogInformation("MealPlanAutoGeneratedEventHandler stopped");
    }

    private async Task ProcessEventAsync(CompanyCustomerMealPlanAutoGeneratedEvent @event, CancellationToken cancellationToken)
    {
        _logger.LogInformation(
            "Auto-generated meal plan created: CompanyCustomerMealPlanId={MealPlanId}, CompanyCustomerId={CustomerId}, Period={StartDate} to {EndDate}",
            @event.CompanyCustomerMealPlanId,
            @event.CompanyCustomerId,
            @event.StartDate.ToString("yyyy-MM-dd"),
            @event.EndDate.ToString("yyyy-MM-dd"));

        // TODO: Add additional processing here:
        // - Send notification to customer about auto-generated meal plan
        // - Log analytics/metrics
        // - Trigger other business processes
        // - Update cache or read models

        await Task.CompletedTask;
    }
}
